    (1, 12, 5596, 6068, E'[{"start":"01:33:16,581","end":"01:33:18,750","text":"I love you!"},{"start":"01:33:20,718","end":"01:33:22,553","text":"Oh, Mr. Moon, are you okay?"},{"start":"01:33:22,587","end":"01:33:24,389","text":"Yeah. Never better."},{"start":"01:33:38,703","end":"01:33:40,638","text":"Clay, you back here?"},{"start":"01:33:40,672","end":"01:33:42,306","text":"We''re on next."},{"start":"01:33:52,016","end":"01:33:54,352","text":"- Yeah! - Yeah."},{"start":"01:33:54,385","end":"01:33:57,522","text":"And arrived on the last planet."},{"start":"01:34:00,491","end":"01:34:03,795","text":"but there''s no sign of life on my scanner."},{"start":"01:34:03,828","end":"01:34:05,697","text":"That''s your cue."},{"start":"01:34:05,730","end":"01:34:07,632","text":"Clay, it''s time to go on."},{"start":"01:34:10,034","end":"01:34:12,770","text":"Nothing but an empty cave."},{"start":"01:34:12,804","end":"01:34:14,439","text":"- Clay. - Oh, no."},{"start":"01:34:16,874","end":"01:34:19,343","text":"- Your songs will carry you. - No."},{"start":"01:34:19,377","end":"01:34:21,312","text":"- This is a mistake. - Please."},{"start":"01:34:24,549","end":"01:34:25,883","text":"I''m not ready."},{"start":"01:34:27,752","end":"01:34:29,754","text":"I''m not ready."},{"start":"01:37:39,510","end":"01:37:40,778","text":"We''re heading home."},{"start":"01:38:47,179","end":"01:38:50,215","text":"Oh, my gosh, listen to that crowd."},{"start":"01:38:50,248","end":"01:38:52,583","text":"You are a genius."},{"start":"01:38:55,653","end":"01:38:58,589","text":"Yeah, you got that right, Linda."},{"start":"01:39:01,326","end":"01:39:03,594","text":"Thank you, thank you."},{"start":"01:39:08,166","end":"01:39:10,568","text":"Look, I am very proud of this show."},{"start":"01:39:10,601","end":"01:39:13,205","text":"We did great work here. Great work."},{"start":"01:39:22,880","end":"01:39:26,218","text":"at my theater for many, many years to come."},{"start":"01:39:44,369","end":"